Envoy Proxy.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

title Component diagram for the Envoy Proxy container

Container_Boundary(envoy_proxy, "Envoy Proxy") {
    Component(tls_termination_filter, "TLS Termination Filter", "C++ native core with statically compiled filters", "Handles TLS 1.3 termination, tokenization, and edge routing.")
    Component(circuit_breaker_controller, "Circuit Breaker Controller", "C++ native core", "Manages phased circuit breaking and fallback routing logic.")
}

Rel(tls_termination_filter, circuit_breaker_controller, "Routes processed requests", "Internal gRPC")

@enduml

Audit & Compliance Ledger Container.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(audit_compliance_ledger_container, "Audit & Compliance Ledger Container") {
    Component(ledger_ingestion_service, "Ledger Ingestion Service", "Go", "Consumes decision payloads from message queues and formats them for ledger ingestion.")
    Component(tamper_evident_journal_manager, "Tamper-Evident Journal Manager", "Go / AWS SDK", "Commits cryptographically verifiable audit records to AWS QLDB.")
    Component(compliance_api_controller, "Compliance API Controller", "Go / REST", "Provides endpoints for Compliance & Audit Officers to query decision histories and export reports.")
}

Rel(ledger_ingestion_service, tamper_evident_journal_manager, "Passes formatted records")
Rel(compliance_api_controller, tamper_evident_journal_manager, "Queries audit logs")
@enduml

Amazon ElastiCache / SQS.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

System_Ext(Scoring_Engine_Container, "Scoring Engine Container", "External system container")
System_Ext(Audit_Compliance_Ledger_Container, "Audit & Compliance Ledger Container", "External system container")

Container_Boundary(Amazon_ElastiCache_SQS, "Amazon ElastiCache / SQS") {
    Component(Amazon_ElastiCache_Serverless, "Amazon ElastiCache Serverless", "Redis OSS", "Provides sub-millisecond feature store caching with automated scaling for low-latency feature lookups.")
    Component(Amazon_SQS_DLQ, "Amazon SQS & DLQ", "Standard/FIFO Queue & Dead-Letter Queue", "Decouples real-time ingestion from auditing while preventing data loss.")
}

Rel(Scoring_Engine_Container, Amazon_ElastiCache_Serverless, "Performs low-latency feature lookups", "RESP over TLS")
Rel(Scoring_Engine_Container, Amazon_SQS_DLQ, "Publishes asynchronous audit events", "AWS SDK / HTTPS")
Rel(Amazon_SQS_DLQ, Audit_Compliance_Ledger_Container, "Consumes audit events", "Queue Protocol")

@enduml

Amazon Aurora PostgreSQL.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container(CaseManagementAPIContainer, "Case Management API Container", "Node.js with NestJS", "Handles analyst workflows.")

Container_Boundary(AmazonAuroraPostgreSQL, "Amazon Aurora PostgreSQL") {
    Component(PrimaryWriterDatabaseInstance, "Primary Writer Database Instance", "Amazon Aurora PostgreSQL db.r6g.xlarge", "Handles write operations for case states using pgx over TLS 1.3 with PgBouncer.")
    Component(ReadReplicaDatabaseInstance, "Read Replica Database Instance", "Amazon Aurora PostgreSQL db.r6g.xlarge", "Offloads audit and compliance queries using pgx over TLS 1.3.")
}

Rel(CaseManagementAPIContainer, PrimaryWriterDatabaseInstance, "Executes write operations for case states", "pgx over TLS 1.3 with PgBouncer")
Rel(CaseManagementAPIContainer, ReadReplicaDatabaseInstance, "Offloads audit and compliance queries", "pgx over TLS 1.3")
@enduml

AWS QLDB.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(aws_qldb, "AWS QLDB") {
    Component(Ledger_Journal_Storage_Component, "Ledger Journal Storage Component", "AWS QLDB Journal", "Provides managed, cryptographically secure, append-only journal storage for R-06 auditability.")
    Component(Ion_Document_Storage_Component, "Ion Document Storage Component", "Amazon Ion", "Stores immutable document revisions securely within the ledger.")
    Component(QLDB_PartiQL_API_Component, "QLDB PartiQL API Component", "PartiQL API", "Exposes interfaces for writing and querying tamper-evident records securely.")
}

Rel(Ledger_Journal_Storage_Component, Ion_Document_Storage_Component, "Persists document revisions")
Rel(QLDB_PartiQL_API_Component, Ledger_Journal_Storage_Component, "Executes queries and transactions")
@enduml
